(() => {
"use strict";
const params=new URLSearchParams(location.search),siteSlug=params.get("site")||(window.GROCERY_STOREFRONT_CONFIG&&window.GROCERY_STOREFRONT_CONFIG.siteSlug)||"",preview=params.get("preview")==="1";
const root=document.getElementById("storefrontRoot"),toastNode=document.getElementById("sfToast");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=v=>"৳"+Number(v||0).toLocaleString("en-BD",{maximumFractionDigits:2});
const qs=v=>encodeURIComponent(String(v??""));
let state={website:null,pages:[],documents:[],categories:[],products:[],deliveryZones:[],priceTiers:[],selectedDeliveryArea:"",page:"home",cart:[],wishlist:[],lastOrder:null,lastTrackedOrder:null,filters:{category:"all",sort:"featured",search:"",brand:"all",minPrice:"",maxPrice:"",inStock:false},mobileMenu:false,previewToken:null,previewOnly:false};
const templateInfo={
 "general-supermarket":{brand:"Daily Basket",eyebrow:"YOUR NEIGHBOURHOOD MARKET",heroImage:"https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1400&q=85",hero:"A better basket starts with better choices.",copy:"Everyday essentials, fresh favourites and pantry staples—thoughtfully selected for the people around your table.",badge:"WEEKLY MARKET PICKS",promise:["Fresh every day","Fair everyday value","Delivery that fits your day"],categoryIcons:["🥬","🥛","🍞","🍚","🥤","🧼"]},
 "fresh-produce":{brand:"Field & Fork",eyebrow:"GROWN WITH CARE · GATHERED WITH PURPOSE",heroImage:"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1400&q=85",hero:"Closer to the source. Fresher to your table.",copy:"Seasonal produce, grower stories and beautiful everyday staples—chosen with the land and your kitchen in mind.",badge:"IN SEASON NOW",promise:["Season-led selection","Know your growers","Good food, less fuss"],categoryIcons:["🥕","🍊","🌿","🍅","🥚","🍯"]},
 "express-grocery":{brand:"zipmart",eyebrow:"YOUR QUICK LOCAL STORE",heroImage:"https://images.unsplash.com/photo-1604719312566-8912e9c8a213?auto=format&fit=crop&w=1400&q=85",hero:"Need the good stuff? Get moving.",copy:"Your everyday essentials in a few quick taps. Build your bag, check out and get on with your day.",badge:"QUICK PICKS · QUICK DELIVERY",promise:["Fast add-to-bag","Simple checkout","Local delivery"],categoryIcons:["⚡","🥤","🍫","🥛","🧻","🍌"]},
 "wholesale-bulk":{brand:"Merchant Supply",eyebrow:"PROCUREMENT MADE PRACTICAL",heroImage:"https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1400&q=85",hero:"Dependable supply. Better buying decisions.",copy:"A business-first catalogue with clear pack sizes, minimum quantities and a streamlined repeat-order workflow.",badge:"BUSINESS BUYING PORTAL",promise:["Transparent pack sizes","Volume-ready ordering","One clear order sheet"],categoryIcons:["🌾","🛢️","📦","🥫","🧂","🚚"]}
};
const pageTitles={home:"Home",shop:"Shop All",category:"Category",product:"Product Details",search:"Search Results",cart:"Your Basket",checkout:"Checkout","order-confirmation":"Order Confirmation","order-tracking":"Track Order",about:"Our Story",contact:"Contact Us",faq:"FAQs",delivery:"Delivery Information",returns:"Returns & Refunds",privacy:"Privacy Policy",terms:"Terms & Conditions",account:"My Account",wishlist:"Wishlist",offers:"Special Offers",brands:"Brands",recipes:"Recipes & Ideas","recipe-detail":"Recipe Details",journal:"Journal","store-locator":"Find a Store","bulk-enquiry":"Bulk & Business Enquiry"};
function pageUrl(page,extra={}){const p=new URLSearchParams({site:siteSlug,page,...extra});if(preview)p.set("preview","1");const base=(window.GROCERY_STOREFRONT_CONFIG&&window.GROCERY_STOREFRONT_CONFIG.basePath)||"./";return base+"?"+p.toString();}
function imageUrl(p){return p?.image_url||p?.gallery?.[0]?.url||p?.gallery?.[0]||"";}
function getProduct(id){return state.products.find(p=>p.id===id);}
function getCategory(id){return state.categories.find(c=>c.id===id);}
function tiersFor(product){return state.priceTiers.filter(t=>t.product_id===product?.id&&t.is_active!==false).sort((a,b)=>Number(a.minimum_quantity)-Number(b.minimum_quantity));}
function unitPriceFor(product,quantity){const tiers=tiersFor(product).filter(t=>Number(t.minimum_quantity)<=Number(quantity)).sort((a,b)=>Number(b.minimum_quantity)-Number(a.minimum_quantity));return Number(tiers[0]?.unit_price??product?.price??0);}
function deliveryAreas(){const zones=state.deliveryZones||[];if(zones.length)return zones.map(z=>({name:z.name,fee:Number(z.delivery_fee||0),minimum:Number(z.minimum_order||0),eta:z.eta_label||""}));const areas=state.website?.settings?.delivery?.areas;return Array.isArray(areas)?areas.map(a=>typeof a==="string"?({name:a,fee:Number(state.website?.settings?.delivery?.default_fee||0),minimum:Number(state.website?.settings?.delivery?.minimum_order||0),eta:""}):({name:a.name||a.area||"",fee:Number(a.delivery_fee??a.fee??state.website?.settings?.delivery?.default_fee??0),minimum:Number(a.minimum_order??state.website?.settings?.delivery?.minimum_order??0),eta:a.eta_label||a.eta||""})).filter(a=>a.name):[];}
function selectedDelivery(){const key=String(state.selectedDeliveryArea||"").trim().toLowerCase();return deliveryAreas().find(a=>a.name.trim().toLowerCase()===key)||null;}
function deliveryFeeForArea(){return selectedDelivery()?.fee??0;}
function deliveryMinimumForArea(){return selectedDelivery()?.minimum??0;}
function cartKey(){return "hf-storefront-cart-v2:"+siteSlug;}
function wishKey(){return "hf-storefront-wishlist-v1:"+siteSlug;}
function loadLocal(){try{state.cart=JSON.parse(localStorage.getItem(cartKey())||"[]");}catch(_){state.cart=[];}try{state.wishlist=JSON.parse(localStorage.getItem(wishKey())||"[]");}catch(_){state.wishlist=[];}}
function saveLocal(){try{localStorage.setItem(cartKey(),JSON.stringify(state.cart));localStorage.setItem(wishKey(),JSON.stringify(state.wishlist));}catch(_){notify("Your browser could not save this basket.");}}
function cartCount(){return state.cart.reduce((n,x)=>n+Number(x.quantity||0),0);}
function cartTotal(){return state.cart.reduce((n,x)=>{const p=getProduct(x.product_id);return n+(p?unitPriceFor(p,x.quantity)*Number(x.quantity):0);},0);}
function notify(message){toastNode.textContent=message;toastNode.classList.add("is-visible");clearTimeout(notify.timer);notify.timer=setTimeout(()=>toastNode.classList.remove("is-visible"),2400);}
function docFor(page){return state.documents.find(d=>d.page_key===page)?.document||null;}
function pageCopy(page){const doc=docFor(page);return {title:doc?.page?.title||pageTitles[page]||"Page",heading:doc?.content?.heading||doc?.tree?.find(n=>n.type==="section")?.children?.find(n=>n.type==="heading")?.text||"",description:doc?.content?.description||doc?.tree?.find(n=>n.type==="section")?.children?.find(n=>n.type==="paragraph")?.text||""};}
function activeProducts(){return state.products.filter(p=>Number(p.stock)>0);}
function categoryName(p){return getCategory(p.category_id)?.name||"General";}
function card(p){const img=imageUrl(p),cat=categoryName(p),stock=Number(p.stock)>0,tiers=tiersFor(p),tierNote=tiers.length?'<small class="sf-tier-hint">Volume rates from '+money(Math.min(...tiers.map(t=>Number(t.unit_price))))+'</small>':'';return '<article class="sf-product-card"><a class="sf-product-media" href="'+pageUrl("product",{product:p.id})+'">'+(img?'<img loading="lazy" src="'+esc(img)+'" alt="'+esc(p.name)+'">':'')+'<span class="sf-product-tag">'+(p.compare_at_price&&Number(p.compare_at_price)>Number(p.price)?"SPECIAL":stock?"AVAILABLE":"SOLD OUT")+'</span></a><div class="sf-product-info"><small>'+esc(cat)+'</small><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3><div class="sf-product-bottom"><span class="sf-price">'+money(p.price)+'<small> / '+esc(p.unit||"piece")+'</small>'+(p.compare_at_price?'<del>'+money(p.compare_at_price)+'</del>':'')+tierNote+'</span><button class="sf-add" data-add="'+esc(p.id)+'" '+(!stock?"disabled":"")+' aria-label="Add '+esc(p.name)+' to cart">'+(state.website.template_key==="wholesale-bulk"?"Add to order":"Add to cart")+'</button></div></div></article>';}
function productGrid(products){return products.length?'<div class="sf-product-grid">'+products.map(card).join("")+'</div>':'<div class="sf-empty"><h3>Your product shelf is waiting</h3><p>Add categories and products from the Halal Food admin catalogue to populate this storefront. Sample inventory is not used for real orders.</p><a class="sf-btn secondary" href="'+(preview?"./admin/products-add.html":"#")+'">Manage products</a></div>';}
function pageHead(kicker,title,desc,action=""){return '<header class="sf-page-head"><div><span class="sf-kicker">'+esc(kicker)+'</span><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div>'+action+'</header>';}
function hero(){const t=templateInfo[state.website.template_key]||templateInfo["general-supermarket"],copy=pageCopy("home");const heading=copy.heading&&copy.heading!=="A better way to shop, every day"?copy.heading:t.hero;const description=copy.description&&copy.description!=="Discover carefully selected favourites, fresh picks and everyday essentials."?copy.description:t.copy;const categories=state.categories.slice(0,6);return '<section class="sf-hero"><div class="sf-hero-copy"><span class="sf-kicker">'+esc(t.eyebrow)+'</span><h1>'+esc(heading)+'</h1><p>'+esc(description)+'</p><a class="sf-btn" href="'+pageUrl("shop")+'">Explore the store ↗</a><div class="sf-hero-trust">'+t.promise.map(x=>'<span>✓ '+esc(x)+'</span>').join("　")+'</div></div><div class="sf-hero-media">'+(state.website.brand?.hero_image||t.heroImage?'<img src="'+esc(state.website.brand?.hero_image||t.heroImage)+'" alt="">':'')+'<span class="sf-hero-badge">'+esc(t.badge)+'</span></div></section><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">BROWSE BY CATEGORY</span><h2>Find your kind of good</h2></div><a class="sf-btn secondary" href="'+pageUrl("shop")+'">View all</a></div><div class="sf-category-grid">'+(categories.length?categories.map((c,i)=>'<a class="sf-category-tile" href="'+pageUrl("category",{category:c.slug})+'"><span>'+t.categoryIcons[i%t.categoryIcons.length]+'</span><strong>'+esc(c.name)+' ↗</strong></a>').join(""):'<div class="sf-empty"><h3>Categories coming soon</h3><p>Create your store categories in the admin panel.</p></div>')+'</div></section><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">THE CURRENT EDIT</span><h2>Popular picks</h2><p>Products from your live catalogue</p></div><a class="sf-btn secondary" href="'+pageUrl("shop")+'">Shop all products</a></div>'+productGrid(activeProducts().slice(0,8))+'</section><section class="sf-section sf-content-panel"><span class="sf-kicker">A BETTER WAY TO BUY</span><h2>Good products. Clear choices. Thoughtful service.</h2><div class="sf-category-grid">'+t.promise.map((x,i)=>'<div class="sf-category-tile"><span>'+["✦","✓","↗"][i]+'</span><strong>'+esc(x)+'</strong></div>').join("")+'</div></section>';}
function filteredProducts(){let rows=activeProducts().slice();if(state.filters.category!=="all"){const cat=state.categories.find(c=>c.slug===state.filters.category);rows=rows.filter(p=>p.category_id===cat?.id);}if(state.filters.search){const q=state.filters.search.toLowerCase();rows=rows.filter(p=>(p.name+" "+p.description+" "+categoryName(p)+" "+String(p.attributes?.brand||"")).toLowerCase().includes(q));}if(state.filters.brand!=="all")rows=rows.filter(p=>String(p.attributes?.brand||"").toLowerCase()===state.filters.brand.toLowerCase());if(state.filters.minPrice!=="")rows=rows.filter(p=>Number(p.price)>=Number(state.filters.minPrice));if(state.filters.maxPrice!=="")rows=rows.filter(p=>Number(p.price)<=Number(state.filters.maxPrice));if(state.filters.inStock)rows=rows.filter(p=>Number(p.stock)>0);if(state.filters.sort==="price-low")rows.sort((a,b)=>Number(a.price)-Number(b.price));if(state.filters.sort==="price-high")rows.sort((a,b)=>Number(b.price)-Number(a.price));if(state.filters.sort==="name")rows.sort((a,b)=>a.name.localeCompare(b.name));return rows;}
function shopPage(){if(state.website.template_key==="wholesale-bulk")return wholesaleShopPage();const c=state.categories,brands=[...new Set(activeProducts().map(p=>String(p.attributes?.brand||"").trim()).filter(Boolean))];return pageHead("THE FULL RANGE","Shop all products","Browse the catalogue, refine by category, brand and price, then add your favourites.")+'<div class="sf-toolbar"><div class="sf-filter-row"><button class="sf-chip '+(state.filters.category==="all"?"is-active":"")+'" data-filter-category="all">All</button>'+c.map(x=>'<button class="sf-chip '+(state.filters.category===x.slug?"is-active":"")+'" data-filter-category="'+esc(x.slug)+'">'+esc(x.name)+'</button>').join("")+'</div><select class="sf-sort" id="sfSort" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option></select></div><div class="sf-facet-row"><select id="sfBrandFilter" class="sf-sort" aria-label="Filter by brand"><option value="all">All brands</option>'+brands.map(b=>'<option value="'+esc(b)+'" '+(state.filters.brand.toLowerCase()===b.toLowerCase()?"selected":"")+'>'+esc(b)+'</option>').join("")+'</select><input id="sfMinPrice" class="sf-sort" type="number" min="0" placeholder="Min price" value="'+esc(state.filters.minPrice)+'"><input id="sfMaxPrice" class="sf-sort" type="number" min="0" placeholder="Max price" value="'+esc(state.filters.maxPrice)+'"><label class="sf-stock-filter"><input id="sfInStock" type="checkbox" '+(state.filters.inStock?"checked":"")+'> In stock only</label></div><div id="sfProductResults">'+productGrid(filteredProducts())+'</div>';}
function wholesaleShopPage(){const rows=filteredProducts();return pageHead("BUSINESS BUYING","Wholesale catalogue","Build a multi-product order, compare volume prices and add quantities in one pass.")+'<div class="sf-toolbar"><input id="sfWholesaleSearch" class="sf-sort" style="flex:1;min-width:180px" value="'+esc(state.filters.search)+'" placeholder="Search product or SKU" aria-label="Search wholesale catalogue"><select id="sfSort" class="sf-sort" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option></select></div><div class="sf-table-wrap"><table class="sf-table sf-quick-order"><thead><tr><th>PRODUCT / PACK</th><th>UNIT PRICE</th><th>VOLUME PRICING</th><th>MINIMUM</th><th>AVAILABLE</th><th>ORDER QTY</th><th></th></tr></thead><tbody>'+rows.map(p=>{const tiers=tiersFor(p),min=Math.max(1,Number(p.attributes?.minimum_order_quantity||1));return '<tr><td><strong>'+esc(p.name)+'</strong><br><small>'+esc(p.sku||p.unit||"")+'</small></td><td>'+money(p.price)+' / '+esc(p.unit||"unit")+'</td><td>'+(tiers.length?tiers.map(t=>'<div>'+esc(t.label||("From "+t.minimum_quantity))+' · '+money(t.unit_price)+'</div>').join(""):'—')+'</td><td>'+min+'</td><td>'+Number(p.stock)+'</td><td><input class="sf-quick-qty" type="number" min="0" max="'+Number(p.stock)+'" step="1" value="0" data-quick-qty="'+esc(p.id)+'" aria-label="Quantity for '+esc(p.name)+'"></td><td><button class="sf-add" data-quick-add="'+esc(p.id)+'" '+(Number(p.stock)<=0?"disabled":"")+'>Add</button></td></tr>';}).join("")+'</tbody></table></div><div class="sf-section"><button class="sf-btn" id="sfAddQuickOrder">Add all quantities to order</button></div><div id="sfProductResults" hidden></div>';}
function categoryPage(){const slug=params.get("category")||"",cat=state.categories.find(c=>c.slug===slug);const rows=cat?state.products.filter(p=>p.category_id===cat.id):[];return pageHead("SHOP BY CATEGORY",cat?.name||"Category not found",cat?"Explore products in this collection.":"Choose a category from the shop page.",'<a class="sf-btn secondary" href="'+pageUrl("shop")+'">All products</a>')+productGrid(rows);}
function searchPage(){const q=params.get("q")||"";state.filters.search=q;return pageHead("SEARCH THE STORE","Search results",q?'Results for “'+q+'”':'Search the product catalogue.')+'<form class="sf-toolbar" id="sfSearchForm"><input class="sf-sort" style="flex:1;min-width:180px" name="q" value="'+esc(q)+'" placeholder="Search products, categories…" aria-label="Search products"><button class="sf-btn">Search</button></form>'+productGrid(filteredProducts());}
function productPage(){const p=getProduct(params.get("product"));if(!p)return '<div class="sf-empty"><h3>Product not found</h3><p>This product may be unavailable or removed from the catalogue.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Back to shop</a></div>';const img=imageUrl(p),qtyMin=Math.max(1,Number(p.attributes?.minimum_order_quantity||1));return '<div class="sf-product-detail"><div class="sf-gallery-main">'+(img?'<img src="'+esc(img)+'" alt="'+esc(p.name)+'">':'')+'</div><div class="sf-product-copy"><span class="sf-kicker">'+esc(categoryName(p))+'</span><h1>'+esc(p.name)+'</h1><div class="sf-product-price">'+money(p.price)+' <small style="font-size:12px;color:var(--sf-muted)">/ '+esc(p.unit||"piece")+'</small></div><p>'+esc(p.description||"Carefully selected for your everyday needs.")+'</p><p><span class="sf-status-pill">'+(Number(p.stock)>0?"In stock":"Currently unavailable")+'</span>　<small>SKU: '+esc(p.sku||"—")+'</small></p>'+(p.attributes?.minimum_order_quantity?'<p>Minimum order: '+qtyMin+' '+esc(p.unit||"units")+'</p>':'')+'<div class="sf-product-actions"><label class="sf-qty"><button type="button" data-qty="-1">−</button><input id="sfProductQty" type="number" min="'+qtyMin+'" max="'+Math.max(qtyMin,Number(p.stock))+'" value="'+qtyMin+'"><button type="button" data-qty="1">+</button></label><button class="sf-btn" data-add="'+esc(p.id)+'" '+(Number(p.stock)<=0?"disabled":"")+'>'+ (state.website.template_key==="wholesale-bulk"?"Add to order":"Add to cart")+'</button><button class="sf-btn secondary" data-buy-now="'+esc(p.id)+'" '+(Number(p.stock)<=0?"disabled":"")+'>'+ (state.website.template_key==="wholesale-bulk"?"Request supply":"Buy now")+'</button></div><button class="sf-chip" data-wish="'+esc(p.id)+'">'+(state.wishlist.includes(p.id)?"♥ Saved to wishlist":"♡ Save to wishlist")+'</button><div class="sf-content-panel" style="margin-top:24px"><h3>Product information</h3><p>'+esc(p.description||"Product information will be updated by the store owner.")+'</p></div></div></div><section class="sf-section"><div class="sf-section-head"><h2>You may also like</h2></div>'+productGrid(state.products.filter(x=>x.id!==p.id&&x.category_id===p.category_id).slice(0,4))+'</section>';}
function cartRows(){return state.cart.map(item=>{const p=getProduct(item.product_id);if(!p)return "";return '<div class="sf-cart-row"><a href="'+pageUrl("product",{product:p.id})+'">'+(imageUrl(p)?'<img src="'+esc(imageUrl(p))+'" alt="">':'<div class="sf-product-media"></div>')+'</a><div><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3><small>'+money(p.price)+' / '+esc(p.unit||"piece")+'</small><div class="sf-cart-controls"><button data-cart-qty="-1" data-product="'+esc(p.id)+'">−</button><b>'+Number(item.quantity)+'</b><button data-cart-qty="1" data-product="'+esc(p.id)+'">+</button><button data-remove="'+esc(p.id)+'" aria-label="Remove product">Remove</button></div></div><strong>'+money(unitPriceFor(p,item.quantity)*Number(item.quantity))+'</strong></div>';}).join("");}
function cartPage(){if(!cartCount())return '<div class="sf-empty"><h3>Your basket is taking a breather</h3><p>Find something good and add it to your basket.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Start shopping</a></div>';return pageHead("YOUR SELECTION","Your basket","Review quantities and make sure everything is just right.")+'<div class="sf-cart-layout"><div class="sf-cart-list">'+cartRows()+'</div>'+summaryCard(false)+'</div>';}
function summaryCard(checkout=false){const delivery=checkout?deliveryFeeForArea():Number(state.website.settings?.delivery?.default_fee||0);return '<aside class="sf-summary"><h3>Order summary</h3><div class="sf-summary-line"><span>Items ('+cartCount()+')</span><b>'+money(cartTotal())+'</b></div><div class="sf-summary-line" data-delivery-fee><span>'+(checkout?"Delivery fee":"Estimated delivery")+'</span><b>'+money(delivery)+'</b></div><div class="sf-summary-total" data-order-total><span>Total</span><strong>'+money(cartTotal()+delivery)+'</strong></div><small data-delivery-note style="color:var(--sf-muted)">'+(checkout?(selectedDelivery()?"Delivery fee and minimum order are based on your selected area.":"Select a delivery area to calculate the final delivery fee."):"Final delivery charge is confirmed by the store at checkout.")+'</small><div style="margin-top:18px">'+(checkout?'<button class="sf-btn" type="submit" form="sfCheckoutForm" style="width:100%" '+(!deliveryAreas().length?"disabled":"")+'>Place COD order →</button>':'<a class="sf-btn" style="width:100%" href="'+pageUrl("checkout")+'">Continue to checkout →</a>')+'</div><p><a href="'+pageUrl("shop")+'">← Continue shopping</a></p></aside>';}
function checkoutPage(){if(!cartCount())return cartPage();const areas=deliveryAreas();return pageHead("ALMOST THERE","Checkout","Complete your details. Delivery charges are calculated from the store's configured service areas.")+'<div class="sf-checkout-layout"><form class="sf-form-card" id="sfCheckoutForm"><h3>Delivery details</h3><div class="sf-form-grid"><div class="sf-field"><label for="sfName">Full name *</label><input id="sfName" name="name" required maxlength="120" autocomplete="name"></div><div class="sf-field"><label for="sfPhone">Phone number *</label><input id="sfPhone" name="phone" required maxlength="24" autocomplete="tel" inputmode="tel"></div><div class="sf-field full"><label for="sfAddress">Full delivery address *</label><textarea id="sfAddress" name="address" required maxlength="600" autocomplete="street-address"></textarea></div><div class="sf-field"><label for="sfArea">Delivery area *</label><select id="sfArea" name="area" required '+(!areas.length?"disabled":"")+'><option value="">Select your delivery area</option>'+areas.map(a=>'<option value="'+esc(a.name)+'" '+(state.selectedDeliveryArea===a.name?"selected":"")+'>'+esc(a.name)+' · '+money(a.fee)+(a.eta?" · "+esc(a.eta):"")+'</option>').join("")+'</select><small>'+(areas.length?"The exact area fee and minimum order are applied again by the server.":"This store has not configured delivery areas yet. Checkout is unavailable until the owner adds a real delivery zone.")+'</small></div><div class="sf-field"><label for="sfPostcode">Postcode</label><input id="sfPostcode" name="postcode" maxlength="20" autocomplete="postal-code"></div><div class="sf-field full"><label for="sfNotes">Delivery notes</label><textarea id="sfNotes" name="notes" maxlength="1000" placeholder="Optional instructions"></textarea></div></div><div class="sf-content-panel"><strong>Payment method</strong><p>Cash on delivery (COD). Pay when your order arrives.</p></div><p><label><input type="checkbox" required> I confirm that my delivery information is correct.</label></p><button class="sf-btn" id="sfPlaceOrder" type="submit" '+(!areas.length?"disabled":"")+'>Place COD order</button><p id="sfCheckoutError" role="alert" style="color:#b42318"></p></form>'+summaryCard(true)+'</div>';}
function orderConfirmation(){const order=state.lastOrder||(()=>{try{return JSON.parse(sessionStorage.getItem("hf-last-order:"+siteSlug)||"null");}catch(_){return null;}})();if(!order)return '<div class="sf-empty"><h3>No recent order in this browser</h3><p>Use Track Order to look up an existing order.</p><a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a></div>';return '<div class="sf-content-panel" style="text-align:center;padding:clamp(28px,6vw,70px)"><span style="font-size:46px">✓</span><span class="sf-kicker">ORDER RECEIVED</span><h1 style="font-family:var(--sf-display);font-size:clamp(34px,5vw,54px)">Thank you. We have your order.</h1><p>Your order number is</p><h2 style="font-size:26px;color:var(--sf-primary)">'+esc(order.order_number)+'</h2><p>Total: <strong>'+money(order.total)+'</strong> · Cash on delivery</p><p>Keep this order number and your phone number to track progress.</p><a class="sf-btn" href="'+pageUrl("order-tracking",{order:order.order_number})+'">Track your order</a></div>';}
function trackingPage(){return pageHead("ORDER SUPPORT","Track your order","Enter the order number and the phone number used at checkout.")+'<div class="sf-content-panel"><form id="sfTrackForm" class="sf-form-grid"><div class="sf-field"><label for="sfOrderNumber">Order number</label><input id="sfOrderNumber" name="order" value="'+esc(params.get("order")||"")+'" required placeholder="HF-XXXXXXXXXX"></div><div class="sf-field"><label for="sfTrackPhone">Phone number</label><input id="sfTrackPhone" name="phone" required inputmode="tel"></div><div class="sf-field full"><button class="sf-btn">Track order</button></div></form><div id="sfTrackResult"></div></div>';}
function contentPage(key){
const copy=pageCopy(key),title=copy.title||pageTitles[key]||"Information",doc=docFor(key),content=doc?.content||{},blocks=Array.isArray(content.blocks)?content.blocks:[],faq=Array.isArray(content.faqs)?content.faqs:[];
const renderBlock=b=>'<section class="sf-rich-block"><h2>'+esc(b.heading||"")+'</h2>'+(Array.isArray(b.paragraphs)?b.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join(""):"")+(Array.isArray(b.bullets)?'<ul>'+b.bullets.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':"")+(Array.isArray(b.faqs)?b.faqs.map(x=>'<details class="sf-faq-item"><summary>'+esc(x.question)+'</summary><p>'+esc(x.answer)+'</p></details>').join(""):"")+'</section>';
let body=blocks.length?blocks.map(renderBlock).join(""):'<section class="sf-rich-block"><h2>'+esc(copy.heading||"More information")+'</h2><p>'+esc(copy.description||"Please contact the store for further information.")+'</p></section>';
if(faq.length)body+='<section class="sf-rich-block"><h2>Frequently asked questions</h2>'+faq.map(x=>'<details class="sf-faq-item"><summary>'+esc(x.question)+'</summary><p>'+esc(x.answer)+'</p></details>').join("")+'</section>';
const cta=key==="account"?'<a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a>':key==="contact"?'<a class="sf-btn secondary" href="'+pageUrl("order-tracking")+'">Order support & tracking</a>':key==="bulk-enquiry"?'<a class="sf-btn" href="'+pageUrl("bulk-enquiry")+'">Open business enquiry</a>':"";
return pageHead("THE STORE",title,copy.description||"Helpful information from the store.")+'<div class="sf-content-panel sf-rich-content">'+body+(cta?'<div class="sf-rich-cta">'+cta+'</div>':"")+'</div>';
}
function offersPage(){const rows=activeProducts().filter(p=>Number(p.compare_at_price)>Number(p.price));return pageHead("THE GOOD VALUE EDIT","Special offers","Offers are calculated from the live product prices and compare-at prices in your catalogue.")+productGrid(rows);}
function brandsPage(){const brands=[...new Set(activeProducts().map(p=>String(p.attributes?.brand||"").trim()).filter(Boolean))];return pageHead("MEET THE MAKERS","Brands","Discover the makers and product ranges carried by this store.")+(brands.length?'<div class="sf-category-grid">'+brands.map(b=>'<a class="sf-category-tile" href="'+pageUrl("search",{q:b})+'"><span>✦</span><strong>'+esc(b)+' ↗</strong></a>').join("")+'</div>':'<div class="sf-empty"><h3>Brand directory is being curated</h3><p>Add brand names to product attributes in the admin catalogue to show them here.</p></div>')+productGrid(activeProducts().slice(0,4));}
function recipesPage(){const copy=pageCopy("recipes"),items=docFor("recipes")?.content?.recipes||[],descriptions=["A practical idea built around familiar pantry ingredients and a few fresh additions.","A simple combination for a balanced everyday meal. Adjust ingredients to your taste.","A flexible meal-prep idea for busy weekdays and shared tables.","A quick way to use seasonal ingredients before your next shop."];return pageHead("IDEAS FOR YOUR TABLE",copy.title||"Recipes & ideas",copy.description||"Inspiration for everyday cooking.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"Cook something lovely")+'</h2><p>Explore approachable ideas, then browse the catalogue for ingredients and everyday favourites.</p></div><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">FROM OUR KITCHEN</span><h2>Ideas to try</h2></div></div><div class="sf-category-grid">'+(items.length?items.map((name,i)=>'<a class="sf-category-tile" href="'+pageUrl("recipe-detail",{recipe:qs(name)})+'"><span>'+["🥗","🍲","🥕","🍞"][i%4]+'</span><strong>'+esc(name)+' ↗</strong><small>'+esc(descriptions[i%descriptions.length])+'</small></a>').join(""):'<p>Recipe ideas are being prepared.</p>')+'</div></section><section class="sf-section"><div class="sf-section-head"><h2>Shop the ingredients</h2><a class="sf-btn secondary" href="'+pageUrl("shop")+'">View all</a></div>'+productGrid(activeProducts().slice(0,8))+'</section>';}
function recipeDetailPage(){const copy=pageCopy("recipe-detail");return pageHead("FROM THE RECIPE JOURNAL",copy.title||"Recipe details",copy.description||"A recipe story from the store.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"Ingredients and method")+'</h2><p>Recipe ingredients, preparation steps and serving notes can be written and saved in the page editor. Related products from the live catalogue are shown below.</p></div><section class="sf-section">'+productGrid(activeProducts().slice(0,4))+'</section>';}
function journalPage(){const copy=pageCopy("journal"),posts=docFor("journal")?.content?.posts||[],slug=params.get("article"),article=posts.find(p=>p.slug===slug);if(article){return pageHead("THE STORE JOURNAL",article.title,article.excerpt,'<a class="sf-btn secondary" href="'+pageUrl("journal")+'">← All stories</a>')+'<article class="sf-blog-article">'+(article.image_url?'<img class="sf-blog-cover" src="'+esc(article.image_url)+'" alt="'+esc(article.title)+'">':"")+'<div class="sf-blog-meta">'+esc(article.category||"Journal")+' · '+esc(article.read_time||"3 min read")+'</div>'+(article.body||[]).map(p=>'<p>'+esc(p)+'</p>').join("")+'<div class="sf-blog-end"><a class="sf-btn" href="'+pageUrl("shop")+'">Explore products</a><a class="sf-btn secondary" href="'+pageUrl("journal")+'">More stories</a></div></article>';}return pageHead("NOTES, STORIES & UPDATES",copy.title||"Journal",copy.description||"Stories and useful updates from the store.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"From our world")+'</h2><p>Practical guides and ideas selected for this store and its customers.</p></div><section class="sf-section"><div class="sf-blog-grid">'+(posts.length?posts.map(p=>'<article class="sf-blog-card">'+(p.image_url?'<a href="'+pageUrl("journal",{article:p.slug})+'"><img loading="lazy" src="'+esc(p.image_url)+'" alt="'+esc(p.title)+'"></a>':"")+'<div class="sf-blog-card-body"><div class="sf-blog-meta">'+esc(p.category||"Journal")+' · '+esc(p.read_time||"3 min read")+'</div><h2><a href="'+pageUrl("journal",{article:p.slug})+'">'+esc(p.title)+'</a></h2><p>'+esc(p.excerpt)+'</p><a class="sf-text-link" href="'+pageUrl("journal",{article:p.slug})+'">Read story ↗</a></div></article>').join(""):'<div class="sf-empty"><h3>Stories are being prepared</h3><p>Check back soon for new articles.</p></div>')+'</div></section>';}
function storeLocatorPage(){const delivery=state.website.settings?.delivery||{},areas=Array.isArray(delivery.areas)?delivery.areas:[];return pageHead("LOCAL SERVICE","Find a store or delivery area","Check the locations and areas configured by the store.")+'<div class="sf-content-panel"><h2>Where we serve</h2>'+(areas.length?'<ul>'+areas.map(x=>'<li>'+esc(typeof x==="string"?x:x.name||x.area||"Service area")+'</li>').join("")+'</ul>':'<p>Verified service zones have not been configured yet. The store owner must add real delivery areas and pickup addresses before this page can publish location details.</p>')+'<p>'+esc(delivery.note||"Delivery coverage is confirmed by the store at checkout.")+'</p><a class="sf-btn secondary" href="'+pageUrl("contact")+'">Ask about delivery</a></div>';}
function bulkEnquiryPage(){return pageHead("BUSINESS CUSTOMERS","Bulk & business enquiry","Request a formal supply quotation. Your enquiry is saved securely for the store team to review.")+'<form class="sf-form-card" id="sfBulkEnquiry"><div class="sf-form-grid"><div class="sf-field"><label for="sfBulkCompany">Business / company name *</label><input id="sfBulkCompany" name="company_name" required maxlength="180"></div><div class="sf-field"><label for="sfBulkContact">Contact person *</label><input id="sfBulkContact" name="contact_name" required maxlength="160"></div><div class="sf-field"><label for="sfBulkPhone">Business phone *</label><input id="sfBulkPhone" name="phone" required inputmode="tel" maxlength="24"></div><div class="sf-field"><label for="sfBulkEmail">Business email</label><input id="sfBulkEmail" name="email" type="email" maxlength="254"></div><div class="sf-field"><label for="sfBulkType">Business type</label><select id="sfBulkType" name="business_type"><option value="">Choose business type</option><option>Retail shop</option><option>Restaurant / café</option><option>Caterer</option><option>Institution</option><option>Distributor</option><option>Other</option></select></div><div class="sf-field"><label for="sfBulkTax">Tax / business ID</label><input id="sfBulkTax" name="tax_id" maxlength="100"></div><div class="sf-field full"><label for="sfBulkNeed">Products, pack sizes and quantities *</label><textarea id="sfBulkNeed" name="message" required minlength="5" maxlength="4000" placeholder="Example: Premium rice 25 kg × 20 bags&#10;Cooking oil 5 L × 12 cartons"></textarea></div><div class="sf-field full"><button class="sf-btn" id="sfBulkSubmit" type="submit">Submit quote request</button><small id="sfBulkStatus" role="status"></small></div></div></form>';}
function returnsPage(){return pageHead("ORDER CARE","Returns & refunds","Submit a return request for an order that has been delivered. The store will review it before any refund or exchange.")+'<form class="sf-form-card" id="sfReturnForm"><div class="sf-form-grid"><div class="sf-field"><label for="sfReturnOrder">Order number *</label><input id="sfReturnOrder" name="order" required placeholder="HF-XXXXXXXXXX"></div><div class="sf-field"><label for="sfReturnPhone">Checkout phone number *</label><input id="sfReturnPhone" name="phone" required inputmode="tel"></div><div class="sf-field full"><label for="sfReturnReason">Reason for return *</label><textarea id="sfReturnReason" name="reason" required minlength="5" maxlength="1000" placeholder="Describe the issue with the delivered order"></textarea></div><div class="sf-field full"><label for="sfReturnNotes">Additional information</label><textarea id="sfReturnNotes" name="notes" maxlength="1000" placeholder="Optional details"></textarea></div><div class="sf-field full"><button class="sf-btn" id="sfReturnSubmit">Submit return request</button><p id="sfReturnStatus" role="status"></p></div></div></form>';}
function wishlistPage(){const rows=state.products.filter(p=>state.wishlist.includes(p.id));return pageHead("YOUR SAVED ITEMS","Wishlist","Keep the products you want to come back to.")+productGrid(rows);}
function renderFooter(){return '<footer class="sf-footer"><div class="sf-footer-inner"><div><h3>'+esc(state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name)+'</h3><p>'+(esc(state.website.brand?.tagline||"Thoughtful products, clear choices and service you can count on."))+'</p></div><div><h4>Shop</h4><div class="sf-footer-links"><a href="'+pageUrl("shop")+'">All products</a><a href="'+pageUrl("cart")+'">Your basket</a><a href="'+pageUrl("wishlist")+'">Wishlist</a></div></div><div><h4>Help</h4><div class="sf-footer-links"><a href="'+pageUrl("contact")+'">Contact</a><a href="'+pageUrl("faq")+'">FAQs</a><a href="'+pageUrl("delivery")+'">Delivery</a><a href="'+pageUrl("returns")+'">Returns</a><a href="'+pageUrl("order-tracking")+'">Track order</a></div></div><div><h4>Information</h4><div class="sf-footer-links"><a href="'+pageUrl("about")+'">Our story</a><a href="'+pageUrl("offers")+'">Special offers</a><a href="'+pageUrl("brands")+'">Brands</a><a href="'+pageUrl("recipes")+'">Recipes</a><a href="'+pageUrl("journal")+'">Journal</a><a href="'+pageUrl("store-locator")+'">Find a store</a><a href="'+pageUrl("bulk-enquiry")+'">Business enquiry</a><a href="'+pageUrl("privacy")+'">Privacy</a><a href="'+pageUrl("terms")+'">Terms</a></div></div></div><div class="sf-footer-bottom">© '+new Date().getFullYear()+' '+esc(state.website.brand?.name||state.website.name)+'. All rights reserved.</div></footer>';}
function renderShell(){const brand=state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name;const nav=[["home","Home"],["shop","Shop"],["offers","Offers"],["brands","Brands"],["recipes","Recipes"],["journal","Journal"],["about","Our story"],["store-locator","Find a store"],["delivery","Delivery"],["faq","FAQs"],["bulk-enquiry","Business"],["contact","Contact"],["order-tracking","Track order"]];return (preview?'<div class="sf-preview-bar"><strong>PRIVATE PREVIEW</strong> · This site is not public. Orders cannot be placed until it is published.</div>':'')+'<div class="sf-announcement">'+esc(state.website.brand?.announcement||"Thoughtful shopping · Reliable local service")+'</div><header class="sf-header"><div class="sf-header-inner"><a class="sf-brand" href="'+pageUrl("home")+'"><span class="sf-brand-mark">'+esc(brand.slice(0,2).toUpperCase())+'</span><span class="sf-brand-copy"><strong>'+esc(brand)+'</strong><small>'+esc(templateInfo[state.website.template_key]?.eyebrow||"ONLINE STORE")+'</small></span></a><form class="sf-search" id="sfHeaderSearch"><span>⌕</span><input name="q" placeholder="Search products and categories…" aria-label="Search products"></form><div class="sf-header-actions"><a class="sf-icon-btn" href="'+pageUrl("wishlist")+'">♡ Saved</a><a class="sf-cart-btn" href="'+pageUrl("cart")+'">Basket <span class="sf-cart-count">'+cartCount()+'</span></a><button class="sf-menu-btn" id="sfMenuToggle" aria-expanded="false" aria-label="Open menu">☰</button></div></div><nav class="sf-nav '+(state.mobileMenu?"is-open":"")+'" id="sfNav">'+nav.map(([key,label])=>'<a href="'+pageUrl(key)+'" '+(state.page===key?'aria-current="page"':'')+'>'+label+'</a>').join("")+'</nav></header>';}
function renderPage(){const key=state.page;switch(key){case"home":return hero();case"shop":return shopPage();case"category":return categoryPage();case"product":return productPage();case"search":return searchPage();case"cart":return cartPage();case"checkout":return checkoutPage();case"order-confirmation":return orderConfirmation();case"order-tracking":return trackingPage();case"wishlist":return wishlistPage();case"offers":return offersPage();case"brands":return brandsPage();case"recipes":return recipesPage();case"recipe-detail":return recipeDetailPage();case"journal":return journalPage();case"store-locator":return storeLocatorPage();case"bulk-enquiry":return bulkEnquiryPage();case"returns":return returnsPage();case"about":case"contact":case"faq":case"delivery":case"privacy":case"terms":case"account":return contentPage(key);default:{const doc=docFor(key);if(doc)return contentPage(key);return '<div class="sf-empty"><h3>Page not found</h3><p>This page is not available in the current site.</p><a class="sf-btn" href="'+pageUrl("home")+'">Go home</a></div>';}}}
function render(){const brand=state.website.brand||{},template=state.website.template_key;document.body.dataset.template=template;document.title=(pageTitles[state.page]||"Store")+" · "+(brand.name||templateInfo[template]?.brand||state.website.name);const main=renderPage();root.innerHTML=(state.previewOnly?'<div role="status" style="padding:11px 18px;text-align:center;background:#fff4d8;color:#714b12;font:600 13px/1.5 Arial,sans-serif;border-bottom:1px solid #ead39a">TEMPLATE PREVIEW · Connect and publish this store from the WordPress admin to enable its live catalogue and checkout.</div>':'')+renderShell()+'<main class="sf-main">'+main+'</main>'+renderFooter()+(template==="express-grocery"&&cartCount()?'<div class="sf-mobile-cart"><div><span>YOUR BAG</span><br><strong>'+cartCount()+' items · '+money(cartTotal())+'</strong></div><a class="sf-btn" href="'+pageUrl("cart")+'">View basket →</a></div>':'');bind();}
function bind(){root.querySelector("#sfMenuToggle")?.addEventListener("click",()=>{state.mobileMenu=!state.mobileMenu;root.querySelector("#sfNav")?.classList.toggle("is-open",state.mobileMenu);root.querySelector("#sfMenuToggle")?.setAttribute("aria-expanded",String(state.mobileMenu));});root.querySelector("#sfHeaderSearch")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfSearchForm")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfSort")?.addEventListener("change",e=>{state.filters.sort=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfCheckoutForm")?.addEventListener("submit",submitOrder);root.querySelector("#sfReturnForm")?.addEventListener("submit",submitReturnRequest);root.querySelector("#sfArea")?.addEventListener("change",e=>{state.selectedDeliveryArea=e.target.value;const fee=deliveryFeeForArea(),minimum=deliveryMinimumForArea();const feeNode=root.querySelector("[data-delivery-fee] b"),totalNode=root.querySelector("[data-order-total] strong"),note=root.querySelector("[data-delivery-note]");if(feeNode)feeNode.textContent=money(fee);if(totalNode)totalNode.textContent=money(cartTotal()+fee);if(note)note.textContent=minimum>0?"Minimum order for this area: "+money(minimum)+". Delivery fee is revalidated by the server.":"Delivery fee is revalidated by the server when you place the order.";});root.querySelector("#sfBrandFilter")?.addEventListener("change",e=>{state.filters.brand=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});["sfMinPrice","sfMaxPrice"].forEach(id=>root.querySelector("#"+id)?.addEventListener("change",e=>{state.filters[id==="sfMinPrice"?"minPrice":"maxPrice"]=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();}));root.querySelector("#sfInStock")?.addEventListener("change",e=>{state.filters.inStock=e.target.checked;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfWholesaleSearch")?.addEventListener("input",e=>{const q=e.target.value.trim().toLowerCase();root.querySelectorAll(".sf-quick-order tbody tr").forEach(row=>{row.hidden=q!==""&&!row.textContent.toLowerCase().includes(q);});});root.querySelector("#sfTrackForm")?.addEventListener("submit",trackOrder);root.querySelector("#sfBulkEnquiry")?.addEventListener("submit",submitQuote);bindDynamic();}
function bindDynamic(){root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>addToCart(b.dataset.add)));root.querySelector("[data-reorder-tracked]")?.addEventListener("click",reorderTrackedOrder);root.querySelectorAll("[data-quick-add]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.quickAdd,qty=Number(root.querySelector('[data-quick-qty="'+id+'"]')?.value||0);if(qty>0)addToCart(id,qty);else notify("Enter a quantity greater than zero.");}));root.querySelector("#sfAddQuickOrder")?.addEventListener("click",()=>{const selected=[...root.querySelectorAll("[data-quick-qty]")].map(input=>({id:input.dataset.quickQty,quantity:Number(input.value||0)})).filter(x=>x.quantity>0);if(!selected.length){notify("Enter at least one product quantity.");return;}for(const item of selected){const p=getProduct(item.id),minimum=Number(p?.attributes?.minimum_order_quantity||1),existing=state.cart.find(x=>x.product_id===item.id),next=(existing?.quantity||0)+item.quantity;if(!p||item.quantity<minimum||next>Number(p.stock)){notify("Check the minimum order and available stock for each selected product.");return;}}for(const item of selected){const existing=state.cart.find(x=>x.product_id===item.id);if(existing)existing.quantity+=item.quantity;else state.cart.push({product_id:item.id,quantity:item.quantity});}saveLocal();notify(selected.length+" product lines added to your order.");render();});root.querySelectorAll("[data-buy-now]").forEach(b=>b.addEventListener("click",()=>{addToCart(b.dataset.buyNow,Number(root.querySelector("#sfProductQty")?.value)||1,true);}));root.querySelectorAll("[data-wish]").forEach(b=>b.addEventListener("click",()=>toggleWish(b.dataset.wish)));root.querySelectorAll("[data-filter-category]").forEach(b=>b.addEventListener("click",()=>{state.filters.category=b.dataset.filterCategory;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());root.querySelectorAll("[data-filter-category]").forEach(x=>x.classList.toggle("is-active",x===b));bindDynamic();}));root.querySelectorAll("[data-cart-qty]").forEach(b=>b.addEventListener("click",()=>changeCart(b.dataset.product,Number(b.dataset.cartQty))));root.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{state.cart=state.cart.filter(x=>x.product_id!==b.dataset.remove);saveLocal();render();}));root.querySelectorAll("[data-qty]").forEach(b=>b.addEventListener("click",()=>{const input=root.querySelector("#sfProductQty");if(input)input.value=Math.max(Number(input.min)||1,Math.min(Number(input.max)||999,Number(input.value||1)+Number(b.dataset.qty)));}));}
function addToCart(id,quantity=1,buyNow=false){const p=getProduct(id);if(!p||Number(p.stock)<=0){notify("This product is currently unavailable.");return;}const qty=Math.max(Number(p.attributes?.minimum_order_quantity||1),Number(quantity)||1);const row=state.cart.find(x=>x.product_id===id);const next=(row?.quantity||0)+qty;if(next>Number(p.stock)){notify("The requested quantity is not available in stock.");return;}if(row)row.quantity=next;else state.cart.push({product_id:id,quantity:qty});saveLocal();notify("Added to your basket.");if(buyNow)location.href=pageUrl("checkout");else render();}
function changeCart(id,delta){const row=state.cart.find(x=>x.product_id===id),p=getProduct(id);if(!row)return;row.quantity=Math.max(0,Math.min(Number(p?.stock||0),Number(row.quantity)+delta));state.cart=state.cart.filter(x=>x.quantity>0);saveLocal();render();}
function toggleWish(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];saveLocal();notify(state.wishlist.includes(id)?"Saved to wishlist.":"Removed from wishlist.");render();}
async function submitOrder(e){e.preventDefault();const error=root.querySelector("#sfCheckoutError"),btn=root.querySelector("#sfPlaceOrder");if(preview){error.textContent="Orders are disabled in private preview. Publish the website before accepting customer orders.";return;}if(!cartCount()){error.textContent="Your basket is empty.";return;}const form=new FormData(e.currentTarget);const customer={name:String(form.get("name")||"").trim(),phone:String(form.get("phone")||"").trim()};const area=String(form.get("area")||"").trim();if(!area){error.textContent="Choose a configured delivery area before placing the order.";return;}const minimum=deliveryMinimumForArea();if(minimum>0&&cartTotal()<minimum){error.textContent="The minimum order for this delivery area is "+money(minimum)+".";return;}const shipping={name:customer.name,phone:customer.phone,address:String(form.get("address")||"").trim(),area,postcode:String(form.get("postcode")||"").trim()};const items=state.cart.map(x=>({product_id:x.product_id,quantity:x.quantity}));btn.disabled=true;btn.textContent="Submitting order…";error.textContent="";try{const result=await window.HFNeonBuilderApi.placeOrder(siteSlug,items,customer,shipping,String(form.get("notes")||""));state.lastOrder=result;try{sessionStorage.setItem("hf-last-order:"+siteSlug,JSON.stringify(result));}catch(_){}state.cart=[];saveLocal();location.href=pageUrl("order-confirmation",{order:result.order_number});}catch(err){error.textContent=err.message||"Order could not be submitted. Please check your details and try again.";btn.disabled=false;btn.textContent="Place COD order";}}
async function trackOrder(e){e.preventDefault();const form=new FormData(e.currentTarget),box=root.querySelector("#sfTrackResult");box.textContent="Checking order…";try{const result=await window.HFNeonBuilderApi.trackOrder(siteSlug,String(form.get("order")||""),String(form.get("phone")||""));if(!result){state.lastTrackedOrder=null;box.innerHTML='<p role="alert">No order matched those details. Check the order number and phone number.</p>';return;}state.lastTrackedOrder=result;const statuses=["pending","processing","shipped","delivered"];const current=statuses.indexOf(result.status);box.innerHTML='<div class="sf-content-panel"><span class="sf-kicker">ORDER '+esc(result.order_number)+'</span><h2>Current status: '+esc(result.status)+'</h2><p>Total '+money(result.total)+' · Payment '+esc(result.payment_status)+'</p><div class="sf-timeline">'+statuses.map((s,i)=>'<span class="'+(i<=current?"is-done":"")+'">'+s+'</span>').join("")+'</div><ul>'+result.items.map(x=>'<li>'+esc(x.product?.name||"Product")+' × '+esc(x.quantity)+' — '+money(x.line_total)+'</li>').join("")+'</ul>'+(result.items?.length?'<button type="button" class="sf-btn" data-reorder-tracked>Buy these items again</button>':'')+'</div>';bindDynamic();}catch(err){box.textContent=err.message||"Order lookup failed.";}}
function reorderTrackedOrder(){const items=state.lastTrackedOrder?.items||[],ready=[];for(const item of items){const id=item.product?.id,p=getProduct(id),quantity=Number(item.quantity||0);if(!p||quantity<=0||quantity<Number(p.attributes?.minimum_order_quantity||1))continue;const current=state.cart.find(x=>x.product_id===id),next=(current?.quantity||0)+quantity;if(next>Number(p.stock))continue;ready.push({id,quantity});}if(!ready.length){notify("The previous order's products are no longer available in the required quantities.");return;}for(const item of ready){const row=state.cart.find(x=>x.product_id===item.id);if(row)row.quantity+=item.quantity;else state.cart.push({product_id:item.id,quantity:item.quantity});}saveLocal();notify("Available items from your previous order were added to the basket.");location.href=pageUrl("cart");}
async function submitQuote(e){e.preventDefault();const form=e.currentTarget,status=root.querySelector("#sfBulkStatus"),button=root.querySelector("#sfBulkSubmit"),data=new FormData(form);button.disabled=true;status.textContent="Saving your quote request…";try{const message=String(data.get("message")||"").trim(),items=message.split(/\\r?\\n/).map(line=>line.trim()).filter(Boolean).slice(0,100).map(description=>({description}));const business={company_name:String(data.get("company_name")||"").trim(),contact_name:String(data.get("contact_name")||"").trim(),phone:String(data.get("phone")||"").trim(),email:String(data.get("email")||"").trim(),business_type:String(data.get("business_type")||""),tax_id:String(data.get("tax_id")||"").trim()};const result=await window.HFNeonBuilderApi.submitQuoteRequest(siteSlug,business,items,message);status.textContent=(result?.message||"Your quote request has been received.")+" Reference: "+(result?.quote_number||"saved");form.reset();}catch(err){status.textContent=err.message||"Your quote request could not be saved. Please try again.";}finally{button.disabled=false;}}
async function submitReturnRequest(e){e.preventDefault();const form=e.currentTarget,status=root.querySelector("#sfReturnStatus"),button=root.querySelector("#sfReturnSubmit"),data=new FormData(form);button.disabled=true;status.textContent="Submitting your return request…";try{const result=await window.HFNeonBuilderApi.submitReturnRequest(siteSlug,String(data.get("order")||""),String(data.get("phone")||""),String(data.get("reason")||""),String(data.get("notes")||""));status.textContent=(result?.message||"Your return request has been submitted.")+" Reference: "+(result?.id||"received");form.reset();}catch(err){status.textContent=err.message||"The return request could not be submitted. Please check the order details.";}finally{button.disabled=false;}}
async function getPreviewToken(){if(!preview)return null;const client=await window.HFNeonClientReady;if(!client)throw new Error("Independent Neon authentication is unavailable.");const {data,error}=await client.auth.getSession();if(error||!data?.session?.user?.id)throw new Error("Sign in to the independent WordPress workspace to preview this draft.");return null;}
async function boot(){if(!siteSlug){throw new Error("A storefront site address is required.");}state.previewToken=await getPreviewToken();const data=await window.HFNeonBuilderApi.loadStorefrontData(siteSlug,{token:state.previewToken,preview});state.website=data.website;state.pages=data.pages;state.documents=data.documents;state.categories=data.categories;state.products=data.products;state.deliveryZones=data.deliveryZones||[];state.priceTiers=data.priceTiers||[];state.previewOnly=!!data.previewOnly;state.page=params.get("page")||"home";if(!state.pages.some(p=>p.page_key===state.page)&&!state.documents.some(d=>d.page_key===state.page))state.page="home";loadLocal();render();}
boot().catch(err=>{console.error("Storefront load failed",err);root.innerHTML='<main class="sf-main"><div class="sf-empty"><h3>Storefront could not be opened</h3><p>'+esc(err.message||"Please try again later.")+'</p>'+(preview?'<a class="sf-btn" href="./admin/website-pages.html">Back to Website Pages</a>':'')+'</div></main>';});
})();